patches.diff:
From 975bff0d462c60d7cfd0af46e72a7e0372fd4b8d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:48:37 +0100
Subject: [PATCH] applets/taskmanager: show window buttons for borderless
 maximized windows

When KWin hides the titlebar of maximized windows, the active window had
no visible minimize, restore or close buttons unless an extra widget was
added. Its Task Manager entry now shows these buttons in that case.

BUG: 444734
---
 applets/taskmanager/backend.cpp  | 17 +++++++++++
 applets/taskmanager/backend.h    |  7 +++++
 applets/taskmanager/qml/Task.qml | 49 ++++++++++++++++++++++++++++++++
 3 files changed, 73 insertions(+)

diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..87c8f4dc9d 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -60,6 +60,7 @@ Backend::Backend(QObject *parent)
     : QObject(parent)
     , m_actionGroup(new QActionGroup(this))
     , m_activityManagerPluginsSettingsWatcher(KConfigWatcher::create(m_activityManagerPluginsSettings.sharedConfig()))
+    , m_kwinConfigWatcher(KConfigWatcher::create(KSharedConfig::openConfig(QStringLiteral("kwinrc"))))
 {
     connect(m_activityManagerPluginsSettingsWatcher.get(),
             &KConfigWatcher::configChanged,
@@ -71,6 +72,17 @@ Backend::Backend(QObject *parent)
                 }
             });

+    m_borderlessMaximizedWindows = m_kwinConfigWatcher->config()->group(QStringLiteral("Windows")).readEntry("BorderlessMaximizedWindows", false);
+    connect(m_kwinConfigWatcher.get(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group, const QByteArrayList &names) {
+        if (group.name() == QLatin1String("Windows") && names.contains(QByteArrayLiteral("BorderlessMaximizedWindows"))) {
+            const bool borderless = group.readEntry("BorderlessMaximizedWindows", false);
+            if (m_borderlessMaximizedWindows != borderless) {
+                m_borderlessMaximizedWindows = borderless;
+                Q_EMIT borderlessMaximizedWindowsChanged();
+            }
+        }
+    });
+
     s_instances.append(this);
     setupShortcuts();
 }
@@ -106,6 +118,11 @@ void Backend::setHasActiveTask(bool active)
     }
 }

+bool Backend::borderlessMaximizedWindows() const
+{
+    return m_borderlessMaximizedWindows;
+}
+
 bool Backend::showsOnlyCurrentScreen() const
 {
     return m_showsOnlyCurrentScreen;
diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..f3b2a90520 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -50,6 +50,7 @@ public:
     Q_PROPERTY(int screen READ screen WRITE setScreen NOTIFY screenChanged)
     Q_PROPERTY(bool hasActiveTask READ hasActiveTask WRITE setHasActiveTask NOTIFY hasActiveTaskChanged)
     Q_PROPERTY(bool showsOnlyCurrentScreen READ showsOnlyCurrentScreen WRITE setShowsOnlyCurrentScreen NOTIFY showsOnlyCurrentScreenChanged)
+    Q_PROPERTY(bool borderlessMaximizedWindows READ borderlessMaximizedWindows NOTIFY borderlessMaximizedWindowsChanged)

     explicit Backend(QObject *parent = nullptr);
     ~Backend() override;
@@ -77,6 +78,8 @@ public:
     bool showsOnlyCurrentScreen() const;
     void setShowsOnlyCurrentScreen(bool shows);

+    bool borderlessMaximizedWindows() const;
+
 Q_SIGNALS:
     void addLauncher(const QUrl &url) const;

@@ -85,6 +88,7 @@ Q_SIGNALS:
     void screenChanged();
     void hasActiveTaskChanged();
     void showsOnlyCurrentScreenChanged();
+    void borderlessMaximizedWindowsChanged();

     void activateTaskAtIndexRequested(int index);
     void activatePreviousTaskRequested();
@@ -117,4 +121,7 @@ private:

     KActivityManagerdPluginsSettings m_activityManagerPluginsSettings;
     KConfigWatcher::Ptr m_activityManagerPluginsSettingsWatcher;
+
+    bool m_borderlessMaximizedWindows = false;
+    KConfigWatcher::Ptr m_kwinConfigWatcher;
 };
diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..1240c499d6 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -74,6 +74,9 @@ PlasmaCore.ToolTipArea {
     readonly property bool hasAudioStream: audioStreams.length > 0
     readonly property bool playingAudio: hasAudioStream && audioStreams.some(item => !item.corked)
     readonly property bool muted: hasAudioStream && audioStreams.every(item => item.muted)
+    // With borderless maximized windows the active window has no titlebar, so offer its buttons here
+    readonly property bool showWindowButtons: !inPopup && !tasksRoot.iconsOnly && backend.borderlessMaximizedWindows
+        && model.IsWindow && !model.IsGroupParent && model.IsActive && model.IsMaximized

     readonly property bool highlighted: (inPopup && activeFocus) || (!inPopup && containsMouse)
         || (task.contextMenu && task.contextMenu.status === PlasmaExtras.Menu.Open)
@@ -622,6 +625,7 @@ PlasmaCore.ToolTipArea {
             leftMargin: taskFrame.margins.left + iconBox.width + TaskManagerApplet.LayoutMetrics.labelMargin
             topMargin: taskFrame.margins.top
             rightMargin: taskFrame.margins.right + (task.audioStreamIcon !== null && task.audioStreamIcon.visible ? (task.audioStreamIcon.width + TaskManagerApplet.LayoutMetrics.labelMargin) : 0)
+                + (windowButtons.visible ? windowButtons.width + TaskManagerApplet.LayoutMetrics.labelMargin : 0)
             bottomMargin: taskFrame.margins.bottom
         }

@@ -648,6 +652,51 @@ PlasmaCore.ToolTipArea {
         }
     }

+    Row {
+        id: windowButtons
+
+        anchors {
+            right: parent.right
+            rightMargin: taskFrame.margins.right + (task.audioStreamIcon !== null && task.audioStreamIcon.visible ? task.audioStreamIcon.width : 0)
+            verticalCenter: parent.verticalCenter
+        }
+
+        visible: task.showWindowButtons && label.visible
+
+        PlasmaComponents3.ToolButton {
+            visible: task.model.IsMinimizable
+            icon.name: "window-minimize"
+            display: PlasmaComponents3.AbstractButton.IconOnly
+            text: i18nc("@action:button", "Minimize")
+            PlasmaComponents3.ToolTip.text: text
+            PlasmaComponents3.ToolTip.visible: hovered
+            PlasmaComponents3.ToolTip.delay: Kirigami.Units.toolTipDelay
+            onClicked: tasksModel.requestToggleMinimized(task.modelIndex())
+        }
+
+        PlasmaComponents3.ToolButton {
+            visible: task.model.IsMaximizable
+            icon.name: "window-restore"
+            display: PlasmaComponents3.AbstractButton.IconOnly
+            text: i18nc("@action:button", "Restore")
+            PlasmaComponents3.ToolTip.text: text
+            PlasmaComponents3.ToolTip.visible: hovered
+            PlasmaComponents3.ToolTip.delay: Kirigami.Units.toolTipDelay
+            onClicked: tasksModel.requestToggleMaximized(task.modelIndex())
+        }
+
+        PlasmaComponents3.ToolButton {
+            visible: task.model.IsClosable
+            icon.name: "window-close"
+            display: PlasmaComponents3.AbstractButton.IconOnly
+            text: i18nc("@action:button", "Close")
+            PlasmaComponents3.ToolTip.text: text
+            PlasmaComponents3.ToolTip.visible: hovered
+            PlasmaComponents3.ToolTip.delay: Kirigami.Units.toolTipDelay
+            onClicked: tasksModel.requestClose(task.modelIndex())
+        }
+    }
+
     states: [
         State {
             name: "launcher"
-- 
